/* Main container */
.loginContainer {
  display: flex;
  min-height: 100vh;
  width: 100%;
  font-family: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  background-color: #f9fafb;
}

/* Form container */
.loginFormContainer {
  width: 100%;
  padding: 2rem;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  background-color: #ffffff;
  position: relative;
  z-index: 10;
}

.loginFormWrapper {
  max-width: 420px;
  width: 100%;
  animation: fadeIn 0.6s ease-out;
}

@keyframes fadeIn {
  from {
    opacity: 0;
    transform: translateY(10px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* Logo */
.logoContainer {
  display: flex;
  justify-content: center;
  margin-bottom: 2rem;
}

.logo {
  height: 60px;
  object-fit: contain;
}

/* Form header */
.formHeader {
  text-align: center;
  margin-bottom: 2rem;
}

.loginTitle {
  font-size: 2rem;
  font-weight: 700;
  color: #111827;
  margin-bottom: 0.5rem;
  letter-spacing: -0.025em;
}

.loginSubtitle {
  font-size: 1rem;
  color: #6b7280;
  font-weight: 400;
}

/* Form */
.loginForm {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.formGroup {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.formLabel {
  font-size: 0.875rem;
  font-weight: 500;
  color: #374151;
}

.passwordHeader {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.forgotPasswordLink {
  background: none;
  border: none;
  font-size: 0.875rem;
  color: #6366f1;
  cursor: pointer;
  padding: 0;
  text-decoration: none;
  transition: color 0.2s;
}

.forgotPasswordLink:hover {
  color: #4f46e5;
  text-decoration: underline;
}

.inputWrapper {
  position: relative;
  display: flex;
  align-items: center;
}

.inputIcon {
  position: absolute;
  left: 1rem;
  color: #9ca3af;
  font-size: 1.25rem;
}

.formInput {
  width: 100%;
  padding: 0.75rem 1rem 0.75rem 3rem;
  border: 1px solid #e5e7eb;
  border-radius: 0.5rem;
  font-size: 1rem;
  background-color: #ffffff;
  transition: all 0.2s;
  color: #1f2937;
}

.formInput:focus {
  outline: none;
  border-color: #6366f1;
  box-shadow: 0 0 0 3px rgba(99, 102, 241, 0.1);
}

.formInput::placeholder {
  color: #9ca3af;
}

.passwordToggle {
  position: absolute;
  right: 1rem;
  background: none;
  border: none;
  color: #9ca3af;
  cursor: pointer;
  font-size: 1.25rem;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: color 0.2s;
}

.passwordToggle:hover {
  color: #6b7280;
}

/* Submit button */
.submitButton {
  margin-top: 0.5rem;
  padding: 0.75rem 1.5rem;
  background: linear-gradient(135deg, #6366f1, #4f46e5);
  color: white;
  border: none;
  border-radius: 0.5rem;
  font-size: 1rem;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.3s;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  height: 3rem;
}

.submitButton:hover {
  background: linear-gradient(135deg, #4f46e5, #4338ca);
  transform: translateY(-1px);
  box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
}

.submitButton:active {
  transform: translateY(0);
  box-shadow: none;
}

.submitButton:disabled {
  background: #e5e7eb;
  color: #9ca3af;
  cursor: not-allowed;
  transform: none;
  box-shadow: none;
}

.buttonIcon {
  font-size: 1.25rem;
}

/* Loading spinner */
.loadingSpinner {
  width: 1.5rem;
  height: 1.5rem;
  border: 2px solid rgba(255, 255, 255, 0.3);
  border-radius: 50%;
  border-top-color: #ffffff;
  animation: spin 0.8s linear infinite;
}

@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}

/* Form footer */
.formFooter {
  margin-top: 2rem;
  text-align: center;
}

.homeLink {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  color: #6b7280;
  text-decoration: none;
  font-size: 0.875rem;
  transition: color 0.2s;
}

.homeLink:hover {
  color: #4b5563;
}

.homeLinkIcon {
  font-size: 1rem;
}

/* Image container */
.loginImageContainer {
  display: none;
  width: 60%;
  background-image: url("/fa8fbe8bfc3c253b06fb8481dde187ff.jpg");
  background-size: cover;
  background-position: center;
  position: relative;
}

.loginImageOverlay {
  height: 100%;
  width: 100%;
  background: linear-gradient(135deg, rgba(79, 70, 229, 0.9), rgba(67, 56, 202, 0.8));
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  color: white;
  padding: 2rem;
}

.imageContent {
  max-width: 600px;
  animation: slideIn 0.8s ease-out;
}

@keyframes slideIn {
  from {
    opacity: 0;
    transform: translateX(30px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

.imageTitle {
  font-size: 3rem;
  font-weight: 700;
  margin-bottom: 1rem;
  letter-spacing: -0.025em;
}

.imageSubtitle {
  font-size: 1.25rem;
  margin-bottom: 3rem;
  line-height: 1.6;
  opacity: 0.9;
}

/* Features section */
.features {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
  margin-top: 2rem;
}

.featureItem {
  display: flex;
  align-items: center;
  gap: 1rem;
  background-color: rgba(255, 255, 255, 0.1);
  padding: 1.25rem;
  border-radius: 0.75rem;
  transition: transform 0.3s, background-color 0.3s;
}

.featureItem:hover {
  background-color: rgba(255, 255, 255, 0.15);
  transform: translateY(-2px);
}

.featureIcon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 3rem;
  height: 3rem;
  background-color: rgba(255, 255, 255, 0.2);
  border-radius: 50%;
  font-size: 1.5rem;
}

.featureText h3 {
  font-size: 1.125rem;
  font-weight: 600;
  margin-bottom: 0.25rem;
}

.featureText p {
  font-size: 0.875rem;
  opacity: 0.8;
}

/* Forgot password modal */
.forgotPasswordModal {
  border-radius: 0.75rem;
  overflow: hidden;
}

.forgotPasswordForm {
  padding: 1.5rem;
}

.modalTitle {
  font-size: 1.5rem;
  font-weight: 600;
  color: #111827;
  margin-bottom: 0.75rem;
}

.modalDescription {
  color: #6b7280;
  margin-bottom: 1.5rem;
  font-size: 0.875rem;
  line-height: 1.5;
}

.resetButton {
  width: 100%;
  padding: 0.75rem;
  background: linear-gradient(135deg, #6366f1, #4f46e5);
