  border: none;
  border-radius: 0.5rem;
  font-size: 1rem;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.3s;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-top: 1rem;
  height: 3rem;
}

.resetButton:hover {
  background: linear-gradient(135deg, #4f46e5, #4338ca);
}

.resetButton:disabled {
  background: #e5e7eb;
  color: #9ca3af;
  cursor: not-allowed;
}

/* Responsive styles */
@media (min-width: 768px) {
  .loginFormContainer {
    width: 50%;
    box-shadow: 0 10px 25px rgba(0, 0, 0, 0.05);
  }

  .loginImageContainer {
    display: block;
    width: 50%;
  }
}

@media (min-width: 1024px) {
  .loginFormContainer {
    width: 40%;
  }

  .loginImageContainer {
    width: 60%;
  }
}

@media (max-width: 767px) {
  .loginFormContainer {
    padding: 1.5rem;
  }

  .loginTitle {
    font-size: 1.75rem;
  }

  .loginSubtitle {
    font-size: 0.875rem;
  }

  .formGroup {
    gap: 0.375rem;
  }

  .submitButton {
    margin-top: 1rem;
  }
}

/* Mobile-specific styles */
@media (max-width: 480px) {
  .loginFormWrapper {
    max-width: 100%;
  }

  .loginTitle {
    font-size: 1.5rem;
  }

  .formHeader {
    margin-bottom: 1.5rem;
  }

  .loginForm {
    gap: 1.25rem;
  }
